  workStatus: z.string().nullable(),
  proposedStart: clock,
  proposedEnd: clock,
  actualStart: z.string().nullable(),
  actualEnd: z.string().nullable(),
  /** Proposed clocks or the traffic management type say the work runs at night. */
  nightWork: z.boolean(),
  simulated: z.boolean(),
